INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'custom', 'n.', '/ˈkʌstəm/', '习俗;风俗;惯例', 'Every culture has its own custom for welcoming a new year.', '每种文化都有迎接新年的习俗。', 'Customs and Traditions', 1, 0, 'senior', 'wordlist', 'required1', 'U4', 'an old custom', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tradition', 'n.', '/trəˈdɪʃn/', '传统;惯例', 'Giving children red packets is a tradition during Spring Festival.', '给孩子发红包是春节期间的一个传统。', 'Customs and Traditions', 2, 0, 'senior', 'wordlist', 'required1', 'U4', 'a long tradition', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ceremony', 'n.', '/ˈserəməni/', '典礼;仪式', 'A special ceremony is held to mark a young person''s coming of age.', '人们举行一个特别的典礼来标志年轻人的成年。', 'Customs and Traditions', 3, 0, 'senior', 'wordlist', 'required1', 'U4', 'a coming-of-age ceremony', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'individual', 'n./adj.', '/ˌɪndɪˈvɪdʒuəl/', '个人;个体;个人的;单独的', 'Today the festival is more of an individual celebration than a family one.', '如今这个节日更像是个人的庆祝,而非家庭的庆祝。', 'Customs and Traditions', 4, 0, 'senior', 'wordlist', 'required1', 'U4', 'an individual celebration', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'perform', 'v.', '/pəˈfɔːm/', '履行;执行;表演', 'Respected elders are invited to perform the ceremony for the boys.', '人们邀请受人尊敬的长辈为男孩们主持这个仪式。', 'Customs and Traditions', 5, 0, 'senior', 'wordlist', 'required1', 'U4', 'perform a ceremony', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'represent', 'v.', '/ˌreprɪˈzent/', '象征;代表', 'The three threads represent three promises the boy makes.', '这三根线象征着男孩许下的三个承诺。', 'Customs and Traditions', 6, 0, 'senior', 'wordlist', 'required1', 'U4', 'represent a promise', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'vary', 'v.', '/ˈveəri/', '(根据情况)变化;不同', 'Coming-of-age traditions vary from culture to culture.', '成人仪式因文化不同而有所差异。', 'Customs and Traditions', 7, 0, 'senior', 'wordlist', 'required1', 'U4', 'vary from culture to culture', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'significantly', 'adv.', '/sɪɡˈnɪfɪkəntli/', '显著地;有重大意义地', 'These customs vary significantly from one region to another.', '这些习俗在不同地区之间差异显著。', 'Customs and Traditions', 8, 0, 'senior', 'wordlist', 'required1', 'U4', 'vary significantly', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'specific', 'adj.', '/spəˈsɪfɪk/', '特有的;具体的;明确的', 'Nearly every society has specific rituals to mark adulthood.', '几乎每个社会都有特定的仪式来标志成年。', 'Customs and Traditions', 9, 0, 'senior', 'wordlist', 'required1', 'U4', 'specific rituals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'symbolise', 'v.', '/ˈsɪmbəlaɪz/', '象征;是……的象征', 'The ceremony is meant to symbolise the change from childhood to adulthood.', '这个仪式旨在象征从童年到成年的转变。', 'Customs and Traditions', 10, 0, 'senior', 'wordlist', 'required1', 'U4', 'symbolise the change', '美式拼 symbolize;美音 /ˈsɪmbəlaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'refer', 'v.', '/rɪˈfɜː(r)/', '提到;谈及;指的是', 'Homecoming refers to a tradition at many American schools.', '校友返校指的是许多美国学校的一种传统。', 'Customs and Traditions', 11, 0, 'senior', 'wordlist', 'required1', 'U4', 'refer to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'graduate', 'v.', '/ˈɡrædʒueɪt/', '毕业;获得学位', 'After you have graduated, you can go back to visit your old campus.', '毕业之后,你可以回去看看你的老校园。', 'Customs and Traditions', 12, 0, 'senior', 'wordlist', 'required1', 'U4', 'graduate from', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'campus', 'n.', '/ˈkæmpəs/', '校园;校区', 'The whole celebration begins on campus with the current students.', '整个庆祝活动从校园里在校生开始。', 'Customs and Traditions', 13, 0, 'senior', 'wordlist', 'required1', 'U4', 'on campus', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'current', 'adj.', '/ˈkʌrənt/', '当前的;现在的', 'The festival starts with the current students at the school.', '这个庆典从学校里现在的在校生开始。', 'Customs and Traditions', 14, 0, 'senior', 'wordlist', 'required1', 'U4', 'current students', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rent', 'v.', '/rent/', '租用;租借', 'Some students rent traditional clothes just for the ceremony.', '有些学生专门为这个仪式租借传统服装。', 'Customs and Traditions', 15, 0, 'senior', 'wordlist', 'required1', 'U4', 'rent a costume', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'senior', 'n./adj.', '/ˈsiːniə(r)/', '高年级学生;年长者;高级的', 'A senior is an older student in the higher grades of a school.', '高年级学生是指学校里年级较高的学生。', 'Customs and Traditions', 16, 0, 'senior', 'wordlist', 'required1', 'U4', 'a senior at school', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'election', 'n.', '/ɪˈlekʃn/', '选举;推选', 'The school holds an election to choose the Homecoming King and Queen.', '学校举行选举来选出返校节的国王和王后。', 'Customs and Traditions', 17, 0, 'senior', 'wordlist', 'required1', 'U4', 'hold an election', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'accompany', 'v.', '/əˈkʌmpəni/', '伴随;陪同', 'A court of princes and princesses will accompany the king and queen.', '一群王子和公主会陪伴着国王和王后。', 'Customs and Traditions', 18, 0, 'senior', 'wordlist', 'required1', 'U4', 'accompany the king', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'court', 'n.', '/kɔːt/', '(返校节的)随从队伍;王宫;法庭', 'The Homecoming Court is made up of first-year students.', '返校节随从队伍由一年级学生组成。', 'Customs and Traditions', 19, 0, 'senior', 'wordlist', 'required1', 'U4', 'the Homecoming Court', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'select', 'v.', '/sɪˈlekt/', '选择;挑选;选拔', 'The king and queen are selected from among the upper-level students.', '国王和王后是从高年级学生中选拔出来的。', 'Customs and Traditions', 20, 0, 'senior', 'wordlist', 'required1', 'U4', 'select from', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'elect', 'v.', '/ɪˈlekt/', '选举;推选', 'The students elected to the court are usually very active at school.', '被选入随从队伍的学生通常在学校里非常活跃。', 'Customs and Traditions', 21, 0, 'senior', 'wordlist', 'required1', 'U4', 'elect to a position', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'involve', 'v.', '/ɪnˈvɒlv/', '使参加;牵涉;包含', 'These students are deeply involved in many school activities.', '这些学生深度参与许多学校活动。', 'Customs and Traditions', 22, 0, 'senior', 'wordlist', 'required1', 'U4', 'be involved in', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stage', 'v./n.', '/steɪdʒ/', '举办;上演;(发展的)阶段', 'Some towns stage a colourful parade for the whole community.', '有些城镇为整个社区举办一场多彩的游行。', 'Customs and Traditions', 23, 0, 'senior', 'wordlist', 'required1', 'U4', 'stage a parade', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'march', 'v.', '/mɑːtʃ/', '齐步走;行进', 'The school band will march through the streets during the parade.', '学校乐队将在游行中穿过街道行进。', 'Customs and Traditions', 24, 0, 'senior', 'wordlist', 'required1', 'U4', 'march in a parade', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'band', 'n.', '/bænd/', '乐队;鼓号队', 'There is always a band playing music at the homecoming dance.', '返校节舞会上总有一支乐队在演奏音乐。', 'Customs and Traditions', 25, 0, 'senior', 'wordlist', 'required1', 'U4', 'a marching band', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'classic', 'adj.', '/ˈklæsɪk/', '典雅的;古朴的;经典的', 'The parade includes the marching band, sports teams and classic cars.', '游行队伍包括鼓号队、运动队和古典老爷车。', 'Customs and Traditions', 26, 0, 'senior', 'wordlist', 'required1', 'U4', 'classic cars', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'socialise', 'v.', '/ˈsəʊʃəlaɪz/', '交往;交际', 'It is a time for the whole town to gather and socialise.', '这是整个城镇聚在一起交际的时刻。', 'Customs and Traditions', 27, 0, 'senior', 'wordlist', 'required1', 'U4', 'socialise with friends', '美式拼 socialize;美音 /ˈsəʊʃəlaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'formal', 'adj.', '/ˈfɔːml/', '正式的;庄重的', 'Some schools keep the dance casual, while others make it a formal affair.', '有些学校把舞会办得随意,而另一些则办得很正式。', 'Customs and Traditions', 28, 0, 'senior', 'wordlist', 'required1', 'U4', 'a formal occasion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'affair', 'n.', '/əˈfeə(r)/', '事情;活动;事件', 'For some schools the dance is quite a grand affair.', '对一些学校来说,这场舞会是相当隆重的活动。', 'Customs and Traditions', 29, 0, 'senior', 'wordlist', 'required1', 'U4', 'a semi-formal affair', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'entire', 'adj.', '/ɪnˈtaɪə(r)/', '全部的;整个的', 'The dance is a time for the entire school to come together.', '这场舞会是整个学校齐聚一堂的时刻。', 'Customs and Traditions', 30, 0, 'senior', 'wordlist', 'required1', 'U4', 'the entire school', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'occasion', 'n.', '/əˈkeɪʒn/', '场合;时机;重要活动', 'A ceremony was held to mark the special occasion.', '人们举行了一个仪式来纪念这个特别的场合。', 'Customs and Traditions', 31, 0, 'senior', 'wordlist', 'required1', 'U4', 'mark the occasion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'duty', 'n.', '/ˈdjuːti/', '责任;义务;职责', 'Becoming an adult means taking on a greater sense of duty.', '成年意味着承担起更大的责任感。', 'Customs and Traditions', 32, 0, 'senior', 'wordlist', 'required1', 'U4', 'a sense of duty', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'marriage', 'n.', '/ˈmærɪdʒ/', '婚姻;结婚', 'In the past, girls learned household skills to prepare for marriage.', '过去,女孩们学习家务技能来为婚姻做准备。', 'Customs and Traditions', 33, 0, 'senior', 'wordlist', 'required1', 'U4', 'prepare for marriage', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'youth', 'n.', '/juːθ/', '青年;青春;年轻人', 'The German ceremony is a kind of youth celebration for fourteen-year-olds.', '这个德国仪式是为十四岁的人举办的一种青年庆典。', 'Customs and Traditions', 34, 0, 'senior', 'wordlist', 'required1', 'U4', 'a youth celebration', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adulthood', 'n.', '/ˈædʌlthʊd/', '成年;成年期', 'The ceremony marks a young person''s entry into adulthood.', '这个仪式标志着一个年轻人进入成年。', 'Customs and Traditions', 35, 0, 'senior', 'wordlist', 'required1', 'U4', 'enter adulthood', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'respect', 'v./n.', '/rɪˈspekt/', '尊重;敬重', 'The three promises are to respect knowledge, parents and society.', '这三个承诺是尊重知识、父母和社会。', 'Customs and Traditions', 36, 0, 'senior', 'wordlist', 'required1', 'U4', 'respect knowledge', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'society', 'n.', '/səˈsaɪəti/', '社会;社团', 'Nearly every society has its own way to celebrate growing up.', '几乎每个社会都有自己庆祝成长的方式。', 'Customs and Traditions', 37, 0, 'senior', 'wordlist', 'required1', 'U4', 'respect society', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'celebrate', 'v.', '/ˈselɪbreɪt/', '庆祝;颂扬', 'People hold ceremonies to celebrate this important stage of life.', '人们举行仪式来庆祝人生这一重要阶段。', 'Customs and Traditions', 38, 0, 'senior', 'wordlist', 'required1', 'U4', 'celebrate an occasion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'celebration', 'n.', '/ˌselɪˈbreɪʃn/', '庆祝;庆祝活动', 'The Jugendfeier in Germany is a serious celebration for young people.', '德国的青年礼是为年轻人举办的一种庄重的庆祝活动。', 'Customs and Traditions', 39, 0, 'senior', 'wordlist', 'required1', 'U4', 'a youth celebration', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'prepare', 'v.', '/prɪˈpeə(r)/', '准备;使做好准备', 'Girls were taught cooking and sewing to prepare for the special day.', '女孩们被教授烹饪和缝纫,为这个特别的日子做准备。', 'Customs and Traditions', 40, 0, 'senior', 'wordlist', 'required1', 'U4', 'prepare for', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'responsibility', 'n.', '/rɪˌspɒnsəˈbɪləti/', '责任;职责', 'As adults, young people must shoulder more responsibilities.', '作为成年人,年轻人必须承担更多责任。', 'Customs and Traditions', 41, 0, 'senior', 'wordlist', 'required1', 'U4', 'shoulder responsibilities', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'knowledge', 'n.', '/ˈnɒlɪdʒ/', '知识;学问', 'In India, the boy promises to respect knowledge and his teacher.', '在印度,男孩承诺尊重知识和他的老师。', 'Customs and Traditions', 42, 0, 'senior', 'wordlist', 'required1', 'U4', 'respect knowledge', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'household', 'n./adj.', '/ˈhaʊshəʊld/', '家庭;一家人;家庭的', 'Girls were taught cooking, sewing and other household skills.', '女孩们被教授烹饪、缝纫和其他家务技能。', 'Customs and Traditions', 43, 0, 'senior', 'wordlist', 'required1', 'U4', 'household skills', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ancient', 'adj.', '/ˈeɪnʃənt/', '古代的;古老的', 'In ancient China, a hair-pinning ceremony was held for girls at fifteen.', '在古代中国,人们为十五岁的女孩举行笄礼。', 'Customs and Traditions', 44, 0, 'senior', 'wordlist', 'required1', 'U4', 'in ancient China', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'modern', 'adj.', '/ˈmɒdn/', '现代的;近代的', 'In modern times, the ceremony has become a personal celebration.', '在现代,这个仪式已变成一种个人化的庆祝。', 'Customs and Traditions', 45, 0, 'senior', 'wordlist', 'required1', 'U4', 'in modern times', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gather', 'v.', '/ˈɡæðə(r)/', '聚集;集合', 'Friends and family gather together to celebrate the young adult.', '亲朋好友聚在一起为这位年轻人庆祝。', 'Customs and Traditions', 46, 0, 'senior', 'wordlist', 'required1', 'U4', 'gather together', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u4.01', '①各时态被动(一般现在/过去/将来 + 情态被动)', 'A2', 10, '上外必修一 U4 — 主语是动作的承受者时用被动:一般现在 is/are done、一般过去 was/were done、一般将来 will be done、情态 can/must/should be done。由时间状语或语境判断时态。', 1, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u4.02', '②现在进行时被动(is/are being done)', 'A2', 10, '上外必修一 U4 — 表示''此刻正被……''时用现在进行被动:am/is/are + being + 过去分词。常与 now、at the moment、right now 等连用。', 2, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u4.03', '③现在完成时被动(has/have been done)', 'A2', 10, '上外必修一 U4 — 表示动作已完成并影响现在时用现在完成被动:has/have + been + 过去分词。常与 already、just、so far、recently 等连用;主语为动作承受者。', 3, 'required1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In some Indian families, the sacred thread ceremony ____ when a boy grows up."', 'is performed', 'performs', 'is performing', 'has performing', 'A', 'ceremony 是动作承受者、一般现在的习俗 → is performed。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In ancient China, a hair-pinning ceremony ____ for a girl when she turned fifteen."', 'held', 'was held', 'was holding', 'holds', 'B', 'ancient China 指过去、ceremony 被举行 → was held。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"Next week a coming-of-age ceremony ____ at our school for the senior students."', 'will hold', 'holds', 'will be held', 'is held', 'C', 'Next week 指将来、ceremony 被举办 → will be held。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"The capping ceremony ____ only by respected elders in old times."', 'could perform', 'performs', 'is performing', 'could be performed', 'D', '情态被动:只能被长辈来举行 → could be performed。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"During the ceremony, three strands of thread ____ to the boy as a gift."', 'are given', 'give', 'are giving', 'have giving', 'A', 'thread 是被给予者、一般现在习俗 → are given。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"Last year the festival ____ in the school gymnasium for the whole town."', 'celebrated', 'was celebrated', 'was celebrating', 'celebrates', 'B', 'Last year 指过去、festival 被庆祝 → was celebrated。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"Traditional clothes ____ before the ceremony begins tomorrow."', 'must rent', 'are renting', 'must be rented', 'rents', 'C', '情态被动:衣服必须被租好 → must be rented。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In Germany, the youth celebration ____ ''Jugendfeier'' by local people."', 'calls', 'is calling', 'has called', 'is called', 'D', 'celebration 被称为、一般现在 → is called。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In the past, girls ____ household skills to prepare for marriage."', 'were taught', 'taught', 'were teaching', 'teach', 'A', 'In the past 指过去、girls 是被教者 → were taught。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"At next month''s homecoming, a king and queen ____ from the upper-level students."', 'will select', 'will be selected', 'select', 'are selecting', 'B', 'next month 指将来、king and queen 被选拔 → will be selected。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"The whole occasion ____ with a graceful bow to the parents every year."', 'ends it', 'is ending', 'is ended', 'has ending', 'C', 'every year 指一般现在、occasion 被以鞠躬结束 → is ended。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"The parade ____ through the main streets of the town yesterday afternoon."', 'staged', 'was staging', 'stages', 'was staged', 'D', 'yesterday 指过去、parade 被举办 → was staged。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"At the ceremony, the meaning of each ritual ____ clearly to the young guests."', 'is explained', 'explains', 'is explaining', 'have explained', 'A', 'meaning 被解释、一般现在 → is explained。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In Finland, every new mother ____ a baby box by the government each year."', 'gives', 'is given', 'is giving', 'has giving', 'B', '每年发生的习俗、mother 被给予 → is given。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"The Coming-of-Age Day ____ on the third Monday of May every year."', 'observes', 'is observing', 'is observed', 'has observed', 'C', 'every year、Day 被庆祝 → is observed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In a hospital in Brazil, the gifts ____ to every visitor after the baby was born."', 'gave', 'were giving', 'give', 'were given', 'D', 'was born 表过去、gifts 被赠送 → were given。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"A king and queen ____ at the next homecoming dance, as is the custom."', 'will be elected', 'will elect', 'elect', 'are electing', 'A', 'next、是承受者 → will be elected。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"In Jamaica, a tree ____ on that spot by the parents many years ago."', 'planted', 'was planted', 'was planting', 'plants', 'B', 'years ago 指过去、tree 被栽种 → was planted。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"At the dance, popular music ____ by a DJ or a live band each Friday."', 'plays', 'is playing', 'is played', 'have played', 'C', 'each Friday、music 被演奏 → is played。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.01'), '"Long ago the capping ceremony ____ for boys when they reached twenty."', 'performed', 'was performing', 'performs', 'was performed', 'D', 'Long ago 指过去、ceremony 被举行 → was performed。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Look! The Full Moon ceremony ____ in the hall right now."', 'is being held', 'is holding', 'is held', 'holds', 'A', 'right now + 是承受者 → 现在进行被动 is being held。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Be quiet, please. The sacred thread ____ around the boy''s wrist at the moment."', 'is tying', 'is being tied', 'is tied', 'ties', 'B', 'at the moment + 线被系 → is being tied。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Listen! A speech of encouragement ____ to the young adults right now."', 'is giving', 'is given', 'is being given', 'gives', 'C', 'right now + speech 被发表 → is being given。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"The hall is noisy because the parade floats ____ at this moment."', 'are decorating', 'are decorated', 'decorate', 'are being decorated', 'D', 'at this moment + floats 被装饰 → are being decorated。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Don''t go in now — traditional clothes ____ on the young dancers."', 'are being put', 'are putting', 'are put', 'put', 'A', '正在进行、clothes 被穿上 → are being put。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Look at the stage! The Coming-of-Age Day ceremony ____ in Seoul now."', 'is celebrating', 'is being celebrated', 'is celebrated', 'celebrates', 'B', 'now + 现场 → 现在进行被动 is being celebrated。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"We can''t enter — the gymnasium ____ for tonight''s homecoming dance right now."', 'is preparing', 'is prepared', 'is being prepared', 'prepares', 'C', 'right now + 场馆被布置 → is being prepared。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Quiet, everyone! The king and queen ____ on the stage at this very moment."', 'are electing', 'are elected', 'elect', 'are being elected', 'D', 'at this very moment + 被选 → are being elected。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"The whole town is busy: a homecoming parade ____ down Main Street now."', 'is being staged', 'is staging', 'is staged', 'stages', 'A', 'now + parade 被举办 → is being staged。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Please wait outside. The ceremony hall ____ with flowers for the occasion now."', 'is filling', 'is being filled', 'is filled', 'fills', 'B', 'now + 大厅被布置 → is being filled。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Look over there! Old photos ____ to the returning alumni at the moment."', 'are showing', 'are shown', 'are being shown', 'show', 'C', 'at the moment + 照片被展示 → are being shown。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Listen carefully — the rules of the ceremony ____ to the guests right now."', 'are reading', 'are read', 'read', 'are being read', 'D', 'right now + 规则被宣读 → are being read。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Don''t move the table; the traditional food ____ for the festival at the moment."', 'is being prepared', 'is preparing', 'is prepared', 'prepares', 'A', 'at the moment + 食物被准备 → is being prepared。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"The street is crowded because the marching band ____ for the parade now."', 'is organising', 'is being organised', 'is organised', 'organises', 'B', 'now + 乐队被组织 → is being organised。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Shh! A graceful bow to the parents ____ on the stage at this moment."', 'is performing', 'is performed', 'is being performed', 'performs', 'C', 'at this moment + 鞠躬被表演 → is being performed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Look! The young dancers'' costumes ____ backstage right now."', 'are changing', 'are changed', 'change', 'are being changed', 'D', 'right now + 服装被更换 → are being changed。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Wait a minute — the Homecoming Court ____ for the photo at the moment."', 'is being arranged', 'is arranging', 'is arranged', 'arranges', 'A', 'at the moment + 队伍被安排 → is being arranged。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"You can hear the noise because the stage ____ for the celebration right now."', 'is building', 'is being built', 'is built', 'builds', 'B', 'right now + 舞台被搭建 → is being built。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Look! Gifts ____ to each visitor as the baby''s ceremony goes on now."', 'are handing', 'are handed', 'are being handed', 'hand', 'C', 'now + 礼物被递出 → are being handed。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.02'), '"Keep your voice down — the elders'' speeches ____ to the young guests now."', 'are translating', 'are translated', 'translate', 'are being translated', 'D', 'now + 演讲被翻译 → are being translated。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The sacred thread ____ around the boy''s wrist, so the ritual is now complete."', 'has been tied', 'has tied', 'is tying', 'ties', 'A', '已完成、thread 被系 → has been tied。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The ceremony hall ____ already ____ with flowers, so we can go in."', 'has decorated', 'has been decorated', 'is decorating', 'decorates', 'B', 'already + 大厅被布置好 → has been decorated。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"So far, three coming-of-age ceremonies ____ at our school this term."', 'have held', 'are holding', 'have been held', 'hold', 'C', 'So far + 是承受者 → 现在完成被动 have been held。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The traditional clothes ____ just ____, so the dancers can put them on."', 'have ironed', 'are ironing', 'iron', 'have been ironed', 'D', 'just + 衣服被熨好 → have been ironed。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The king and queen ____ already ____, and now they are receiving flowers."', 'have been elected', 'have elected', 'are electing', 'elect', 'A', 'already + 被选出 → have been elected。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"Recently, many old traditions ____ back to life in our town."', 'have brought', 'have been brought', 'are bringing', 'bring', 'B', 'Recently + 传统被恢复 → have been brought。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The invitations to the homecoming dance ____ already ____ to every student."', 'have sent', 'are sending', 'have been sent', 'send', 'C', 'already + 请柬被寄出 → have been sent。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"Up to now, the meaning of the ritual ____ to all the foreign guests."', 'has explained', 'is explaining', 'explains', 'has been explained', 'D', 'Up to now + 含义被解释 → has been explained。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"A tree ____ just ____ on that spot to mark the baby''s birth."', 'has been planted', 'has planted', 'is planting', 'plants', 'A', 'just + 树被栽 → has been planted。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The whole parade route ____ already ____ for tomorrow''s celebration."', 'has planned', 'has been planned', 'is planning', 'plans', 'B', 'already + 路线被规划 → has been planned。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"So far this week, two speeches of encouragement ____ to the young adults."', 'have given', 'are giving', 'have been given', 'give', 'C', 'So far + 演讲被发表 → have been given。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The gymnasium ____ just ____ for the homecoming dance, so it looks lovely."', 'has cleaned', 'is cleaning', 'cleans', 'has been cleaned', 'D', 'just + 场馆被打扫 → has been cleaned。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"Many gifts ____ already ____ to the visitors at the baby''s ceremony."', 'have been handed', 'have handed', 'are handing', 'hand', 'A', 'already + 礼物被分发 → have been handed。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The bow to the parents ____ just ____, and the ceremony is now over."', 'has performed', 'has been performed', 'is performing', 'performs', 'B', 'just + 鞠躬被完成 → has been performed。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"This year, the day ____ chosen as a national holiday for young people."', 'has', 'is being', 'has been', 'is', 'C', 'This year + 被定为节日 → has been (chosen)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"All the traditional food ____ already ____ for the festival guests."', 'has prepared', 'is preparing', 'prepares', 'has been prepared', 'D', 'already + 食物被准备好 → has been prepared。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The stage ____ just ____, so the celebration can begin at once."', 'has been built', 'has built', 'is building', 'builds', 'A', 'just + 舞台被搭好 → has been built。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"Over the years, this custom ____ down from one generation to the next."', 'has passed', 'has been passed', 'is passing', 'passes', 'B', 'Over the years + 习俗被传承 → has been passed。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"The names of the Homecoming Court ____ already ____ on the school website."', 'have posted', 'are posting', 'have been posted', 'post', 'C', 'already + 名单被公布 → have been posted。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U4' AND code='s1u4.03'), '"Up to now, every part of the ceremony ____ carefully by the elders."', 'has arranged', 'is arranging', 'arranges', 'has been arranged', 'D', 'Up to now + 各环节被安排 → has been arranged。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Jugendfeier in Germany', 'In Germany, the coming-of-age ceremony is called Jugendfeier, which means youth celebration. It is held for young people who are about fourteen years old. The day is an important chance for them to think about many topics that are connected with their future as citizens. During the event, teachers deliver speeches about certain values, such as having respect for other people and developing a sense of duty. These speeches make the whole ceremony more serious than a simple party. The tradition began in the nineteenth century, at a time when people were starting to pay more attention to the rights and duties of ordinary citizens. Today, Jugendfeier reminds young Germans that growing up is not only about freedom but also about taking on real responsibilities. After the ceremony, families often gather together to celebrate the young person''s new stage of life.', '说明·德国青年礼', 141, '[{"q":"What does the word Jugendfeier mean?","answer":"A","options":["A celebration for young people.","A speech given by young citizens.","A national holiday for teachers.","A serious party held for families."],"explanation":"原文 ''Jugendfeier, which means youth celebration'' 的转述。"},{"q":"What do teachers talk about during the event?","answer":"B","options":["The history of Germany only.","Values such as respect and a sense of duty.","How to find a good job.","The cost of the ceremony."],"explanation":"原文 ''speeches about certain values, such as having respect… developing a sense of duty'' 的转述。"},{"q":"What does the ceremony remind young Germans of?","answer":"A","options":["That growing up means taking on responsibilities.","That they can now do anything they like.","That school is finally over.","That they must leave their families."],"explanation":"末段 ''growing up is not only about freedom but also about taking on real responsibilities'' 的转述。"}]'::jsonb, '[{"word":"celebration","cn":"庆祝活动"},{"word":"citizen","cn":"公民"},{"word":"duty","cn":"责任"}]'::jsonb, 2, 'required1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Quinceanera in Latin America', 'In Latin America, the quinceanera is a special celebration for a girl when she turns fifteen. It marks her change from a child into a young woman. In the past, girls were taught cooking, sewing and other household skills before the big day, because the ceremony was closely connected with getting ready for marriage. A traditional party would begin when the girl arrived with her father. He would dance with her first, and then give her away to dance with other relatives and friends. Over the years, however, the meaning of the quinceanera has slowly changed. Today it has become more like an individual celebration of the young person''s coming of age, similar to the way an eighteenth birthday is treated as important in many other cultures. The dancing, the music and the family gathering remain, but the old link with marriage has mostly disappeared.', '说明·拉美女孩成人礼', 145, '[{"q":"At what age does a girl have her quinceanera?","answer":"B","options":["When she turns eighteen.","When she turns fifteen.","When she turns twelve.","When she turns twenty."],"explanation":"原文 ''when she turns fifteen'' 的转述。"},{"q":"Why were girls taught household skills in the past?","answer":"C","options":["To win a school competition.","To become teachers.","To prepare for getting married.","To earn money quickly."],"explanation":"原文 ''connected with getting ready for marriage'' 的转述。"},{"q":"How has the meaning of the quinceanera changed today?","answer":"D","options":["It has been completely forgotten.","It now happens only at school.","It is now only for boys.","It has become a personal coming-of-age celebration."],"explanation":"末段 ''become more like an individual celebration of the young person''s coming of age'' 的转述。"}]'::jsonb, '[{"word":"marriage","cn":"婚姻"},{"word":"individual","cn":"个人的"},{"word":"relative","cn":"亲戚"}]'::jsonb, 2, 'required1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Sacred Thread Ceremony in India', 'In some Indian families, a special ceremony is performed when a boy is old enough to grow up. During the event, he is given three strands of a sacred thread. These three strands stand for three promises that he makes: to respect knowledge, to respect his parents and to respect society. People say that the ceremony marks the start of a new life. Traditionally, the child then leaves his family to go and live with a teacher, who is called a Guru. At this point the boy is said to become twice-born. In Indian thinking, a human being has at least two births. The first one is his ordinary, physical birth. The second one is his intellectual birth, which happens through the care of a teacher. So the ceremony is not only about growing older; it is also about beginning to learn and to take responsibility as a member of society.', '说明·印度圣线礼', 151, '[{"q":"What do the three strands of thread stand for?","answer":"A","options":["Three promises the boy makes.","Three years of school.","Three members of the family.","Three gifts from the Guru."],"explanation":"原文 ''three strands stand for three promises'' 的转述。"},{"q":"Where does the boy traditionally go after the ceremony?","answer":"B","options":["To a faraway city to work.","To live with a teacher called a Guru.","To his grandparents'' home.","To another country."],"explanation":"原文 ''leaves his family to go and live with a teacher, who is called a Guru'' 的转述。"},{"q":"What is the second birth in Indian thinking?","answer":"C","options":["A second physical birth.","The day of his wedding.","His intellectual birth through a teacher''s care.","The birth of his own child."],"explanation":"原文 ''second one is his intellectual birth, which happens through the care of a teacher'' 的转述。"}]'::jsonb, '[{"word":"represent","cn":"象征"},{"word":"knowledge","cn":"知识"},{"word":"intellectual","cn":"智力的"}]'::jsonb, 2, 'required1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Old Ceremonies in Ancient China', 'In ancient China, there were special ceremonies to mark the moment when a young person grew up. For a girl, a hair-pinning ceremony was held when she was fifteen years old. On that day she would wash and comb her hair, and then a ceremony master would carefully put a pin in it. This showed everyone that she was no longer a child. For a boy, a capping ceremony took place when he was about twenty. Respected elders were invited to perform the ceremony and to place a special hat on his head. Both ceremonies were ways of telling the young person that an important new stage in life had arrived. From that point on, he or she was expected to shoulder grown-up responsibilities, while also enjoying a bigger say in his or her own affairs. These customs show how much value old Chinese society placed on growing up.', '说明·中国笄礼与冠礼', 149, '[{"q":"What happened at a girl''s hair-pinning ceremony?","answer":"D","options":["She was given a new name.","She had to leave her home.","She received money from elders.","A master put a pin in her combed hair."],"explanation":"原文 ''a ceremony master would carefully put a pin in it'' 的转述。"},{"q":"Who performed the capping ceremony for boys?","answer":"A","options":["Respected elders.","The boy''s young friends.","A foreign teacher.","The boy himself."],"explanation":"原文 ''Respected elders were invited to perform the ceremony'' 的转述。"},{"q":"What were young people expected to do after these ceremonies?","answer":"B","options":["To stop being a young person at school.","To take on adult responsibilities.","To leave their own affairs to the elders.","To give a special hat to a child."],"explanation":"原文 ''expected to shoulder grown-up responsibilities'' 的转述。"}]'::jsonb, '[{"word":"ancient","cn":"古代的"},{"word":"ceremony","cn":"仪式"},{"word":"responsibility","cn":"责任"}]'::jsonb, 2, 'required1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Coming-of-Age Day in South Korea', 'In South Korea, the third Monday of May is set aside as Coming-of-Age Day. It is the day to celebrate all the young people who turn nineteen that year. Reaching this age means that they can now enjoy the rights that come with being an adult. At the same time, the day reminds them to take on the real duties that adults carry. Many young people dress up in traditional Korean clothes and attend a public ceremony, often held in a city square. One of the most touching parts of the day comes at the end, when the young adults offer a graceful bow to their parents. This bow is a way of saying thank you for all the years of care and love. It also stands for the start of their own journeys in the wider world. Friends and family then gather to share food and good wishes.', '说明·韩国成人日', 149, '[{"q":"When is Coming-of-Age Day held in South Korea?","answer":"C","options":["On the first day of the year.","On every Sunday in spring.","On May''s third Monday.","On the last day of school."],"explanation":"原文 ''the third Monday of May is set aside as Coming-of-Age Day'' 的转述。"},{"q":"What does reaching this age allow young people to do?","answer":"D","options":["To stop going to school.","To travel for free.","To choose a new family.","To enjoy the rights of an adult."],"explanation":"原文 ''enjoy the rights that come with being an adult'' 的转述。"},{"q":"What does the bow to the parents stand for?","answer":"A","options":["Thanks to parents and the start of a new journey.","A wish for more money.","A request to stay at home.","A goodbye to all their friends."],"explanation":"原文 ''a way of saying thank you… stands for the start of their own journeys'' 的转述。"}]'::jsonb, '[{"word":"celebrate","cn":"庆祝"},{"word":"duty","cn":"责任"},{"word":"graceful","cn":"优雅的"}]'::jsonb, 2, 'required1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Homecoming in the United States', 'Homecoming is a well-loved tradition at many American high schools and colleges. It is a time to celebrate the school you are attending, and a time for those who have already graduated to come back, see old friends and remember their school days. Many schools begin their homecoming with Spirit Week. Each day of that week has a fun theme, and students are encouraged to join in. Some schools hold an election to choose a Homecoming King and Queen. A group of younger students, called the Court, will accompany them. Many towns also stage a parade with the school band, sports teams and classic cars. People gather along the streets to cheer and socialise. The week usually ends with a homecoming dance, which is open to every student. Some schools keep it casual, while others make it a more formal affair. Either way, it brings the whole school together.', '说明·美国校友返校', 149, '[{"q":"What can graduated students do at homecoming?","answer":"B","options":["Take new exams.","Come back and see old friends.","Pay the school fees again.","Join a different school."],"explanation":"原文 ''come back, see old friends and remember their school days'' 的转述。"},{"q":"How do many schools begin their homecoming?","answer":"C","options":["With a final test.","With a long holiday.","With a week of themed days called Spirit Week.","With a quiet meeting."],"explanation":"原文 ''begin their homecoming with Spirit Week. Each day… has a fun theme'' 的转述。"},{"q":"What usually ends the homecoming week?","answer":"D","options":["A school exam.","A long parade only.","A trip to another town.","A dance open to every student."],"explanation":"原文 ''ends with a homecoming dance, which is open to every student'' 的转述。"}]'::jsonb, '[{"word":"graduate","cn":"毕业"},{"word":"election","cn":"选举"},{"word":"parade","cn":"游行"}]'::jsonb, 2, 'required1', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'My Coming-of-Age Day', 'Last spring my school held a special (1)____ for all the students who had turned eighteen. We dressed up in clean, smart clothes and walked onto the (2)____ one by one. Our head teacher gave a short (3)____ about what it means to become an adult. She said that growing up is not only about new freedom, but also about taking on real (4)____. After that, each of us made a quiet (5)____ to study hard and to look after our families. The most touching (6)____ came at the end, when we offered a deep bow to our parents to thank them for their (7)____. Many of them could not hold back their tears. That day will always (8)____ in my heart as the moment I truly began to grow (9)____. Now, whenever I face something difficult, I remember the (10)____ I made and try to do my best.', 149, 2, '[{"q":"1","answer":"A","options":["ceremony","machine","garden","market"],"explanation":"a special ceremony 一场特别的典礼。"},{"q":"2","answer":"B","options":["river","stage","shop","kitchen"],"explanation":"walked onto the stage 走上舞台。"},{"q":"3","answer":"C","options":["price","noise","speech","song"],"explanation":"gave a short speech 做简短演讲。"},{"q":"4","answer":"D","options":["holidays","games","jokes","responsibilities"],"explanation":"taking on real responsibilities 承担真正的责任。"},{"q":"5","answer":"A","options":["promise","mistake","noise","price"],"explanation":"made a quiet promise 默默许下承诺。"},{"q":"6","answer":"B","options":["price","moment","machine","garden"],"explanation":"the most touching moment 最动人的时刻。"},{"q":"7","answer":"C","options":["money","noise","love","machine"],"explanation":"thank them for their love 感谢他们的爱。"},{"q":"8","answer":"D","options":["sell","leave","throw","stay"],"explanation":"will always stay in my heart 永远留在心里。"},{"q":"9","answer":"A","options":["up","off","down","out"],"explanation":"grow up 长大。"},{"q":"10","answer":"B","options":["price","promise","noise","machine"],"explanation":"the promise I made 我许下的承诺。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'The Story of the Sacred Thread', 'In an Indian village, a boy named Arun was getting ready for his coming-of-age (1)____. His grandfather explained that he would receive three (2)____ of a sacred thread. Each strand would (3)____ a promise: to respect knowledge, to respect his parents and to respect (4)____. On the morning of the big day, the whole family (5)____ together in the main hall. The thread was carefully (6)____ around Arun''s wrist by an elder. People believe that this moment (7)____ the start of a new life. After the ceremony, a boy would traditionally leave home to live with a (8)____, who would guide him toward learning. Arun felt both nervous and (9)____ as he listened to the old words. He understood that, from that day, he would have to (10)____ the duties of a young adult.', 134, 2, '[{"q":"1","answer":"C","options":["machine","market","ceremony","garden"],"explanation":"coming-of-age ceremony 成人仪式。"},{"q":"2","answer":"D","options":["prices","noises","songs","strands"],"explanation":"three strands 三股线。"},{"q":"3","answer":"A","options":["represent","break","sell","lose"],"explanation":"represent a promise 象征一个承诺。"},{"q":"4","answer":"B","options":["money","society","noise","weather"],"explanation":"respect society 尊重社会。"},{"q":"5","answer":"C","options":["sold","lost","gathered","broke"],"explanation":"gathered together 聚在一起。"},{"q":"6","answer":"D","options":["sold","thrown","eaten","tied"],"explanation":"carefully tied 小心地系上。"},{"q":"7","answer":"A","options":["marks","sells","breaks","loses"],"explanation":"marks the start 标志着开始。"},{"q":"8","answer":"B","options":["price","teacher","shop","city"],"explanation":"live with a teacher 和老师一起生活。"},{"q":"9","answer":"C","options":["angry","bored","proud","asleep"],"explanation":"nervous and proud 紧张又自豪。"},{"q":"10","answer":"D","options":["sell","forget","hide","shoulder"],"explanation":"shoulder the duties 承担责任。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'Getting Ready for the Festival', 'Our town was busy all week, because a big coming-of-age (1)____ was about to take place. In the school hall, parents and teachers worked hard to (2)____ everything. Bright flowers were placed on every (3)____, and traditional clothes were (4)____ for the young dancers to wear. A local (5)____ practised the music they would play during the parade. My job was to help (6)____ the chairs in neat rows. At the same time, a kind elder (7)____ to us why each part of the ceremony mattered. He said that such customs help to (8)____ the past with the present. By Friday evening, the whole hall looked (9)____ and ready. As I looked around, I felt proud to be part of such an old and meaningful (10)____.', 126, 2, '[{"q":"1","answer":"A","options":["festival","machine","market","garden"],"explanation":"coming-of-age festival 成人庆典。"},{"q":"2","answer":"B","options":["sell","prepare","break","lose"],"explanation":"prepare everything 准备好一切。"},{"q":"3","answer":"C","options":["price","noise","table","song"],"explanation":"on every table 在每张桌子上。"},{"q":"4","answer":"D","options":["sold","eaten","thrown","rented"],"explanation":"clothes were rented 衣服被租来。"},{"q":"5","answer":"A","options":["band","price","noise","garden"],"explanation":"a local band 当地乐队。"},{"q":"6","answer":"B","options":["sell","arrange","throw","lose"],"explanation":"arrange the chairs 摆好椅子。"},{"q":"7","answer":"C","options":["sold","lost","explained","broke"],"explanation":"explained why 解释原因。"},{"q":"8","answer":"D","options":["sell","break","lose","connect"],"explanation":"connect the past with the present 把过去和现在相连。"},{"q":"9","answer":"A","options":["lovely","empty","broken","ugly"],"explanation":"looked lovely 看起来很美。"},{"q":"10","answer":"B","options":["price","tradition","machine","market"],"explanation":"a meaningful tradition 有意义的传统。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'A Surprising Birthday Custom', 'When my pen pal in Finland turned one month old, her family followed an unusual (1)____. Long ago, the government began to (2)____ every new mother a large box. Inside the box were small (3)____ such as clothes, sheets and toys for the baby. At first I found this hard to (4)____, but my pen pal said it was a much-loved (5)____ in her country. In Brazil, she told me, a soon-to-be mother often (6)____ gifts and gives them to the visitors who come when the baby is (7)____. Each culture, it seems, has its own special way to (8)____ a new life. These customs (9)____ from country to country, yet they all share one warm (10)____: to welcome a child into the world with love.', 126, 2, '[{"q":"1","answer":"C","options":["machine","market","custom","garden"],"explanation":"an unusual custom 一个不寻常的习俗。"},{"q":"2","answer":"D","options":["sell","throw","lose","give"],"explanation":"give every new mother a box 给每位新妈妈一个盒子。"},{"q":"3","answer":"A","options":["gifts","prices","noises","songs"],"explanation":"small gifts 小礼物。"},{"q":"4","answer":"B","options":["sell","believe","eat","throw"],"explanation":"hard to believe 难以置信。"},{"q":"5","answer":"C","options":["price","noise","tradition","machine"],"explanation":"a much-loved tradition 备受喜爱的传统。"},{"q":"6","answer":"D","options":["sells","breaks","loses","chooses"],"explanation":"chooses gifts 挑选礼物。"},{"q":"7","answer":"A","options":["born","sold","lost","thrown"],"explanation":"when the baby is born 当婴儿出生时。"},{"q":"8","answer":"B","options":["sell","celebrate","break","lose"],"explanation":"celebrate a new life 庆祝新生命。"},{"q":"9","answer":"C","options":["sell","break","vary","lose"],"explanation":"vary from country to country 因国而异。"},{"q":"10","answer":"D","options":["price","noise","machine","wish"],"explanation":"one warm wish 一个温暖的愿望。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'A Day at Homecoming', 'Last autumn I joined the homecoming week at my American friend''s high (1)____. Each day had a fun (2)____, such as crazy hair day or pyjama day, and everyone was happy to join (3)____. On Friday, the school held an (4)____ to choose a Homecoming King and Queen. A group of younger students, called the Court, would (5)____ them through the day. In the afternoon, the whole town came out to watch a (6)____ with the school band, sports teams and classic cars. People stood along the streets to cheer and (7)____ with old friends. In the evening there was a homecoming (8)____, open to every student. Some schools keep it casual, while others make it a more (9)____ affair. For me, the best part was simply feeling that the (10)____ school had come together as one big family.', 139, 2, '[{"q":"1","answer":"A","options":["school","machine","market","garden"],"explanation":"high school 高中。"},{"q":"2","answer":"B","options":["price","theme","noise","song"],"explanation":"a fun theme 有趣的主题。"},{"q":"3","answer":"C","options":["off","out","in","down"],"explanation":"join in 参加。"},{"q":"4","answer":"D","options":["error","song","price","election"],"explanation":"held an election 举行选举。"},{"q":"5","answer":"A","options":["accompany","sell","break","lose"],"explanation":"accompany them 陪伴他们。"},{"q":"6","answer":"B","options":["price","parade","noise","garden"],"explanation":"watch a parade 观看游行。"},{"q":"7","answer":"C","options":["sell","lose","socialise","break"],"explanation":"socialise with old friends 与老友交际。"},{"q":"8","answer":"D","options":["price","noise","machine","dance"],"explanation":"a homecoming dance 返校舞会。"},{"q":"9","answer":"A","options":["formal","empty","broken","ugly"],"explanation":"a more formal affair 更正式的活动。"},{"q":"10","answer":"B","options":["price","entire","noise","machine"],"explanation":"the entire school 整个学校。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U4', 'A Family Tradition I Treasure', 'In my family, there is a quiet little (1)____ that I treasure very much. On the first day of each new year, my grandmother (2)____ us all together in her small living room. She tells old stories about how our family has (3)____ through difficult times. Then each of us makes a simple (4)____ for the year ahead. My grandmother says that such customs help younger people to (5)____ where they come from. She believes that a strong family must always (6)____ knowledge and love from one generation to the next. Over the (7)____, this small custom has never changed, even though the world around us (8)____ so quickly. Whenever I take part, I feel calm and (9)____ to be part of something so old. To me, this tradition is far more (10)____ than any expensive gift.', 137, 2, '[{"q":"1","answer":"C","options":["machine","market","tradition","garden"],"explanation":"a quiet little tradition 一个安静的小传统。"},{"q":"2","answer":"D","options":["sells","breaks","loses","gathers"],"explanation":"gathers us all together 把我们聚在一起。"},{"q":"3","answer":"A","options":["survived","sold","lost","thrown"],"explanation":"has survived through difficult times 度过艰难时光。"},{"q":"4","answer":"B","options":["price","promise","noise","song"],"explanation":"makes a simple promise 许下简单的承诺。"},{"q":"5","answer":"C","options":["sell","break","remember","lose"],"explanation":"remember where they come from 记住自己的来处。"},{"q":"6","answer":"D","options":["sell","break","lose","pass"],"explanation":"pass knowledge from one generation to the next 把知识传给下一代。"},{"q":"7","answer":"A","options":["years","minutes","seconds","metres"],"explanation":"over the years 多年来。"},{"q":"8","answer":"B","options":["sells","changes","breaks","loses"],"explanation":"changes so quickly 变化如此之快。"},{"q":"9","answer":"C","options":["angry","bored","proud","asleep"],"explanation":"calm and proud 平静又自豪。"},{"q":"10","answer":"D","options":["price","noise","machine","precious"],"explanation":"far more precious 珍贵得多。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Talking about Coming of Age', '上外必修一 U4 · dialogue', 3, 'Mia: Tom, when do you think a person really becomes an adult?
