INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 Birthday Customs Around the World', '上外必修一 U4 · passage', 2, 'Different cultures have their own birthday customs.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Writing an Introduction', '上外必修一 U4 · dialogue', 3, 'Zhou: Miss Lee, I have to write an introduction to a Chinese ceremony. Any advice?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 A Tip for a Good Presentation', '上外必修一 U4 · passage', 2, 'Here is a simple tip for giving a good presentation about customs.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Introduce a Chinese Coming-of-Age Ceremony(介绍一种中国成人礼)', 'An Introduction to a Chinese Coming-of-Age Ceremony', '你校正在举办成人礼,一群来自美国高中的学生前来参观。请你用英语写一段约80词的介绍,向美国学生介绍一种中国的成人礼(如古代的笄礼或冠礼),内容包括:① 它在什么时候、为谁举行;② 主要的庆祝活动或环节;③ 它的意义。注意:用一个主题句开头,支撑句围绕中心,用一个结尾句收束,保持段落统一。', 'Your school is holding a coming-of-age ceremony, and a group of American high-school students are coming to visit. Write a paragraph of about 80 words to introduce one Chinese coming-of-age ceremony (such as the ancient hair-pinning or capping ceremony) to them. Include: 1) when and for whom it is held; 2) the main activities; 3) its meaning. Begin with a topic sentence, keep all supporting sentences on one idea, and finish with a concluding sentence.', '["主题句:点明这是中国一种成人礼(In ancient China, … was held to mark …)","时间与对象(It was held for … when they were … years old)","主要环节/活动(During the ceremony, …)","意义 + 结尾句(It showed that … / It reminded young people that …)"]'::jsonb, 70, 100, 'In ancient China, the hair-pinning ceremony was a coming-of-age ceremony held to mark an important moment in a girl''s life. It was performed when she was fifteen years old. During the ceremony, the girl would wash and comb her hair, and then a ceremony master would carefully put a pin in it. This showed everyone that she was no longer a child. The custom reminded young people that, as adults, they should respect their parents and shoulder real responsibilities. In short, it was a meaningful way to welcome a new stage of life.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In ancient China, the hair-pinning ceremony was held to mark an important moment in a girl''s life.","It was performed when she was fifteen years old.","This showed everyone that she was no longer a child.","The custom reminded young people that they should shoulder real responsibilities."]'::jsonb, '[{"wrong":"The ceremony was hold when she was fifteen.","correct":"The ceremony was held when she was fifteen.","note":"被动语态用过去分词 held,不是 hold。"},{"wrong":"A pin was put in her hair by a master carefully.","correct":"A master carefully put a pin in her hair.","note":"有明确施动者且要强调动作时,主动更自然;副词位置也要恰当。"},{"wrong":"It reminded young people they should respect parents.","correct":"It reminded young people that they should respect their parents.","note":"remind sb that … 引导宾语从句,that 不宜省、需用 their。"}]'::jsonb, '【成人礼介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U4', '{"title":"被动语态·各时态 + 现在进行被动 + 现在完成被动 速查","intro":"当主语是动作的承受者(而非发出者)时,用被动语态:be + 过去分词。be 随时态变化。判断口诀:看主语是''做''还是''被做'';再由时间状语/语境定 be 的时态。","table":{"headers":["时态","结构 / 例句"],"rows":[["一般现在被动","am/is/are + 过分:The ceremony is performed every year."],["一般过去被动","was/were + 过分:The ceremony was held last year."],["一般将来被动","will be + 过分:A king will be elected next week."],["情态被动","can/must/should + be + 过分:Clothes must be rented in advance."],["现在进行被动","am/is/are + being + 过分:The thread is being tied now."],["现在完成被动","has/have + been + 过分:The thread has been tied."]]},"specialRules":[{"rule":"主语是动作承受者 → 才用被动;主语自己发出动作 → 用主动","mark":"The hall is decorated(大厅被装饰)"},{"rule":"现在进行被动:正在''被……'',常与 now / at the moment 连用","mark":"is being held(正被举行)"},{"rule":"现在完成被动:已完成且影响现在,常与 already / just / so far 连用","mark":"has been planted(已被栽下)"},{"rule":"情态动词后接 be + 过分;助动词 will 同理 will be + 过分","mark":"must be done / will be done"}],"why":["用被动是为了把焦点放在''被影响的人或事''上;当我们不知道、或不想说出动作的执行者时,被动也最自然。"],"gaokaoPoints":["语法填空:给出动词原形,由时间状语/语境判断时态再变被动(was held / is being held / has been held)。","进行被动与完成被动易混:now → being done;already/just/so far → been done。","主动↔被动转换:by 短语引出执行者,可省略未知或不重要的执行者。"],"examVsReal":[{"exam":"The flag is being raised now.（考试强调正被升起）","real":"They''re raising the flag now.","note":"口语里执行者清楚时常用主动,更简洁"},{"exam":"Laws have been made to govern its use.（考试用完成被动）","real":"They''ve made laws about it.","note":"日常表达常用主动+they/people 泛指施动者"}]}'::jsonb, 'sufe');
